# quotation SHORT and glossed at once (the lint's ninety-character window). Chapter 9 is frozen and skipped.
from beha_ink import *
R = {}
def row(c, v, verdict, prose): R[(c, v)] = (verdict, prose)

# ---- 8:1-26 — the lamps; the Levites purified, waved and given; their ages ----
row(8, 1, 'CONTEXT', 'The frame: "and the LORD spoke to Moses, saying" — the first of the portion\'s eight (computed: 8:1, 8:5, 8:23, 10:1, 11:16, 11:23, 12:4, 12:14; four "said").')
row(8, 2, 'MATERIAL', f'TOWARD THE FACE OF THE LAMPSTAND. "{H(8, 2, "בהעלתך", "את", "הנרת")}" ("when you raise the lamps") → {A(8, 2, "באדלקותך", "ית", "בוציניא")} ("when you KINDLE the lamps") — the raising rendered as lighting; "{H(8, 2, "אל", "מול", "פני", "המנורה")}" ("toward the face of the lampstand" — the clause\'s two seats, 8:2-3, computed) → {A(8, 2, "לקבל", "אפי", "מנרתא")} ("opposite the face of the lampstand"); "{H(8, 2, "יאירו", "שבעת", "הנרות")}" ("the seven lamps shall light" — one seat) → {A(8, 2, "יהון", "מנהרין", "שבעא", "בוציניא")} ("the seven lamps shall be lighting"). THE ARAMAIC LAMP-WORD, בּוֹצִינַיָּא ("the lamps"), returns at 11:5 as "the CUCUMBERS" — one Aramaic word for the two (cut from the shelf\'s bytes, computed).')
row(8, 3, 'MATERIAL', f'AARON DID SO. "{H(8, 3, "ויעש", "כן", "אהרן")}" ("and Aaron did so" — the clause\'s one seat with his name, computed) → {A(8, 3, "ועבד", "כן", "אהרן")} ("and Aaron did so"); "{H(8, 3, "העלה", "נרתיה")}" ("he raised its lamps") → {A(8, 3, "אדלק", "בוצינהא")} ("he KINDLED its lamps") — the raising as lighting again; the run of 8:2 (the register: "and he did", "he raised" — the store\'s glosses).')
row(8, 4, 'MATERIAL', f'BEATEN FROM ITS BASE TO ITS FLOWER; THE VISION. "{H(8, 4, "מקשה", "זהב")}" ("beaten work of gold") → {A(8, 4, "נגידא", "דהב")} ("DRAWN gold" — the beaten word rendered as drawn out); "{H(8, 4, "עד", "ירכה", "עד", "פרחה")}" ("from its base to its flower" — one seat) → {A(8, 4, "עד", "שידה", "עד", "שושנה")} ("to its base, to its LILY") — the flower as the lily; "{H(8, 4, "מקשה", "הוא")}" ("beaten it is" — "beaten" twice in the verse, computed; the Sifrei\'s restatement) → {A(8, 4, "נגידא", "היא")}; "{H(8, 4, "כמראה", "אשר", "הראה")}" ("as the vision which He showed" — one seat) → {A(8, 4, "כחזוא", "די", "אחזי")} ("as the vision He showed"). The base-word ("thigh") shared with the sotah\'s 5:27 and the lampstand of Exod 25:31; the flower-word with Lev 13\'s eruption (computed).')
row(8, 5, 'CONTEXT', 'The frame (the second).')
row(8, 6, 'MATERIAL', f'TAKE THE LEVITES AND PURIFY THEM. "{H(8, 6, "קח", "את", "הלוים")}" ("take the Levites") → {A(8, 6, "קרב", "ית", "לואי")} ("BRING NEAR the Levites") — "take" rendered as the offering verb (as at 3:6 "bring near the tribe"); "{H(8, 6, "וטהרת", "אתם")}" ("and purify them") → {A(8, 6, "ותדכי", "יתהון")} ("and cleanse them"). The Sifrei has NO ROW on 8:5-23 (computed by position: 61 on 8:4, 62 on 8:24) — the Levites\' purification read on Onkelos alone.')
row(8, 7, 'MATERIAL', f'THE WATER OF PURIFICATION; THE RAZOR. "{H(8, 7, "הזה", "עליהם", "מי", "חטאת")}" ("sprinkle on them water of purification" — the phrase\'s one seat, computed; chapter 19\'s heifer-water is called "a purification", 19:9) → {A(8, 7, "אדי", "עליהון", "מיא", "דחטאתא")} ("sprinkle on them the water of the sin-offering"); "{H(8, 7, "והעבירו", "תער", "על", "כל", "בשרם")}" ("and pass a razor over all their flesh") → {A(8, 7, "ויעברון", "מספר", "על", "כל", "בשרהון")} ("pass a SHEARS over all their flesh") — the razor at its two Torah seats, the nazirite\'s 6:5 and this (computed), the Aramaic a different tool-word from the nazirite\'s; "{H(8, 7, "וכבסו", "בגדיהם", "והטהרו")}" ("wash their clothes and cleanse themselves") → {A(8, 7, "ויחורון", "לבושיהון", "וידכון")} ("whiten their garments and be clean").')
row(8, 8, 'MATERIAL', f'TWO BULLS. "{H(8, 8, "ולקחו", "פר", "בן", "בקר", "ומנחתו")}" ("and they shall take a young bull and its meal offering") → {A(8, 8, "ויסבון", "תור", "בר", "תורי", "ומנחתיה")} ("a bull, son of oxen, and its meal offering"); "{H(8, 8, "ופר", "שני", "בן", "בקר", "תקח", "לחטאת")}" ("and a second young bull YOU shall take for a sin offering") → {A(8, 8, "ותור", "תנין", "בר", "תורי", "תסב", "לחטאתא")} — the first bull theirs ("they shall take"), the second Moses\' ("you shall take"): the ink\'s two subjects kept.')
row(8, 9, 'CONTEXT', f'"Gather the whole congregation" → {A(8, 9, "ותכנש", "ית", "כל", "כנשתא")} ("assemble all the assembly") — the people present for the Levites\' offering.')
row(8, 10, 'MATERIAL', f'THE PEOPLE LAY HANDS ON THE LEVITES. "{H(8, 10, "וסמכו", "בני", "ישראל", "את", "ידיהם", "על", "הלוים")}" ("and the children of Israel shall lay their hands on the Levites") → {A(8, 10, "ויסמכון", "בני", "ישראל", "ית", "ידיהון", "על", "לואי")} — the laying of hands, the offerer\'s act on an offering (Lev 1:4), done by a people on men: the Levites as the congregation\'s offering (the register: the spec of 8:20-22).')
row(8, 11, 'MATERIAL', f'A HUMAN WAVE OFFERING — WAVED RENDERED LIFTED AGAIN. "{H(8, 11, "והניף", "אהרן", "את", "הלוים", "תנופה")}" ("and Aaron shall wave the Levites as a wave offering") → {A(8, 11, "וירים", "אהרן", "ית", "לואי", "ארמא")} ("and Aaron shall LIFT the Levites, a LIFTING") — the waving verb and noun rendered by lifting, as at 5:25 and 6:20 (Naso); "{H(8, 11, "והיו", "לעבד", "את", "עבדת", "יהוה")}" ("that they may be to do the service of the LORD") → {A(8, 11, "ויהון", "למפלח", "ית", "פלחנא", "דיי")} ("that they may serve the service of the LORD"). The wave-noun at 8:11, 8:13, 8:15, 8:21 (computed) — the Levites waved three times in the spec and once in the run.')
row(8, 12, 'MATERIAL', f'THE LEVITES LAY HANDS ON THE BULLS. "{H(8, 12, "והלוים", "יסמכו", "את", "ידיהם", "על", "ראש", "הפרים")}" ("and the Levites shall lay their hands on the head of the bulls") → {A(8, 12, "ולואי", "יסמכון", "ית", "ידיהון", "על", "ריש", "תוריא")} — the second laying: the people on the Levites (8:10), the Levites on the bulls; "{H(8, 12, "ועשה", "את", "האחד", "חטאת", "ואת", "האחד", "עלה")}" ("make the one a sin offering and the one a burnt offering") → {A(8, 12, "ויעבד", "ית", "חד", "חטאתא", "וית", "חד", "עלתא")}; "to atone for the Levites" → {A(8, 12, "לכפרא", "על", "לואי")} ("to atone for the Levites").')
row(8, 13, 'CONTEXT', f'"And you shall stand the Levites before Aaron and his sons and wave them a wave offering" → {A(8, 13, "ותרם", "יתהון", "ארמא")} ("and lift them, a lifting") — the second waving.')
row(8, 14, 'MATERIAL', f'SEPARATED — AND SERVING BEFORE ME. "{H(8, 14, "והבדלת", "את", "הלוים", "מתוך", "בני", "ישראל")}" ("and you shall separate the Levites from among the children of Israel") → {A(8, 14, "ותפרש", "ית", "לואי", "מגו", "בני", "ישראל")}; "{H(8, 14, "והיו", "לי", "הלוים")}" ("and the Levites shall be MINE" — the Sifrei\'s "unto Me = forever" list holds this seat, computed) → {A(8, 14, "ויהון", "משמשין", "קדמי", "לואי")} ("and the Levites shall be SERVING before Me") — a verb inserted for the bare possessive (cut from the shelf\'s bytes).')
row(8, 15, 'CONTEXT', f'"And after that the Levites shall come to serve the tent of meeting; you shall purify them and wave them" → {A(8, 15, "ותדכי", "יתהון", "ותרם", "יתהון", "ארמא")} — the third waving.')
row(8, 16, 'MATERIAL', f'GIVEN, GIVEN — THE SECOND SEAT OF THE DOUBLING, TO ME. "{H(8, 16, "כי", "נתנים", "נתנים", "המה", "לי")}" ("for given, given are they to Me") → {A(8, 16, "ארי", "אפרשא", "מפרשין", "אנון", "לי")} ("for SEPARATED, separated are they to Me") — the doubled word rendered by a doubled Aramaic cognate (at 3:9 by two different verbs); THE INK: the doubling stands at TWO seats — 3:9 נְתוּנִם נְתוּנִם ("given, given", spelled with the vav) and here נְתֻנִים נְתֻנִים (spelled with the yod) — a spelling delta between the two writings, and the pronoun moves from "to HIM" (3:9, Aaron) to "to ME" (twice here; computed); 8:19 and 18:6 write it once. The Bamidbar ledger\'s row on 3:9 called 8:16\'s "given" single — CORRECTED at this sitting (appended there). "{H(8, 16, "תחת", "פטרת", "כל", "רחם")}" ("instead of the opening of every womb" — פִּטְרַת the feminine form\'s one seat, computed) → {A(8, 16, "חלף", "פתח", "כל", "ולדא")} ("instead of the opening of every birth").')
row(8, 17, 'MATERIAL', f'MINE, MAN AND BEAST, FROM THE NIGHT I SMOTE. "{H(8, 17, "כי", "לי", "כל", "בכור")}" ("for Mine is every firstborn" — the "unto Me" list\'s seat) → {A(8, 17, "ארי", "דילי", "כל", "בוכרא")}; "{H(8, 17, "ביום", "הכתי", "כל", "בכור")}" ("on the day I smote every firstborn") → {A(8, 17, "ביומא", "דקטלית", "כל", "בוכרא")} ("on the day I KILLED every firstborn") — the smiting rendered as killing; "I sanctified them to Me" → {A(8, 17, "אקדשית", "יתהון", "קדמי")} — the firstborn clause of Exod 13:2 and 3:13 (the Bamidbar cell\'s CALL into the Passover engine — reference, computed at 3:12).')
row(8, 18, 'CONTEXT', f'"And I have taken the Levites instead of every firstborn" → {A(8, 18, "וקרבית", "ית", "לואי", "חלף", "כל", "בוכרא")} ("and I have brought near the Levites instead of every firstborn") — "taken" as "brought near" (the offering verb, as at 8:6).')
row(8, 19, 'MATERIAL', f'GIVEN TO AARON; NO PLAGUE — "THE CHILDREN OF ISRAEL" FIVE TIMES. "{H(8, 19, "ואתנה", "את", "הלוים", "נתנים", "לאהרן")}" ("and I have given the Levites, given, to Aaron") → {A(8, 19, "ויהבית", "ית", "לואי", "מסירין", "לאהרן")} ("given the Levites, HANDED OVER, to Aaron") — the single "given" of this verse rendered by the handing-over word 3:9 used; "{H(8, 19, "ולא", "יהיה", "בבני", "ישראל", "נגף")}" ("that there be no plague among the children of Israel") → {A(8, 19, "ולא", "יהי", "בבני", "ישראל", "מותא")} ("that there be no DEATH among the children of Israel") — the plague as death; "the children of Israel" FIVE TIMES in the one verse (computed — one with the prefixed "among").')
row(8, 20, 'CONTEXT', f'THE RUN OPENS: "And Moses and Aaron and all the congregation did to the Levites" → {A(8, 20, "ועבד", "משה", "ואהרן", "וכל", "כנשתא")}; "as the LORD commanded Moses concerning the Levites, so did the children of Israel to them" — the run\'s doubled formula (the register).')
row(8, 21, 'MATERIAL', f'THE RUN: PURIFIED, WASHED, WAVED, ATONED. "{H(8, 21, "ויתחטאו", "הלוים")}" ("and the Levites purified themselves" — the reflexive, the form\'s one seat; the heifer chapter\'s "purify himself" its kin, computed) → {A(8, 21, "ואדכיו", "לואי")}; "{H(8, 21, "וינף", "אהרן", "אתם", "תנופה")}" ("and Aaron waved them a wave offering") → {A(8, 21, "וארם", "אהרן", "יתהון", "ארמא")} ("and Aaron LIFTED them, a lifting"); "{H(8, 21, "ויכפר", "עליהם", "אהרן", "לטהרם")}" ("and Aaron atoned for them to purify them") → {A(8, 21, "וכפר", "עליהון", "אהרן", "לדכואיהון")} — four narrative verbs (the register, computed).')
row(8, 22, 'CONTEXT', f'"And after that the Levites came to do their service in the tent of meeting before Aaron and before his sons; as the LORD commanded Moses concerning the Levites, so they did to them" → {A(8, 22, "כמא", "די", "פקיד", "יי", "ית", "משה")} — the spec/run pair closed with the formula twice (8:20, 8:22).')
row(8, 23, 'CONTEXT', 'The frame (the third).')
row(8, 24, 'MATERIAL', f'FROM TWENTY-FIVE. "{H(8, 24, "זאת", "אשר", "ללוים")}" ("this is what applies to the Levites") → {A(8, 24, "דא", "די", "ללואי")}; "{H(8, 24, "מבן", "חמש", "ועשרים", "שנה", "ומעלה")}" ("from twenty-five years old and upward" — the age\'s one seat, computed; the parser reads 25) → {A(8, 24, "מבר", "חמש", "ועשרין", "שנין", "ולעלא")}; against chapter 4\'s THIRTY at seven seats and the Writings\' TWENTY at four (1 Chr 23:24, 23:27; 2 Chr 31:17; Ezra 3:8 — computed): a three-setting parameter, the Sifrei reconciling the first two (to learn / to serve) and Chronicles giving its own reason for the third (no more carrying, 1 Chr 23:26).')
row(8, 25, 'MATERIAL', f'FROM FIFTY HE RETURNS. "{H(8, 25, "ומבן", "חמשים", "שנה", "ישוב", "מצבא", "העבדה")}" ("and from fifty years old he shall return from the host of the service" — the age\'s one seat; the parser reads 50) → {A(8, 25, "ומבר", "חמשין", "שנין", "יתוב", "מחיל", "פלחנא")}; "{H(8, 25, "ולא", "יעבד", "עוד")}" ("and shall work no more") → {A(8, 25, "ולא", "יפלח", "עוד")} ("and he shall not serve any more").')
row(8, 26, 'MATERIAL', f'HE SERVES WITH HIS BROTHERS — THE WATCH, NOT THE WORK. "{H(8, 26, "ושרת", "את", "אחיו")}" ("and he shall serve with his brothers" — the clause\'s one seat, computed) → {A(8, 26, "וישמש", "עם", "אחוהי")}; "{H(8, 26, "לשמר", "משמרת", "ועבדה", "לא", "יעבד")}" ("to keep the charge, but service he shall not do") → {A(8, 26, "למטר", "מטרא", "ופלחנא", "לא", "יפלח")}; "{H(8, 26, "ככה", "תעשה", "ללוים", "במשמרתם")}" ("thus shall you do with the Levites in their charges") → {A(8, 26, "כדין", "תעבד", "ללואי", "במטרתהון")} — the Sifrei\'s hinge for years-not-blemishes and the singers\' voice.')

# ---- 10:1-36 — the trumpets; the first march; Hobab; the ark; the signs ----
row(10, 1, 'CONTEXT', 'The frame (the fourth).')
row(10, 2, 'MATERIAL', f'TWO TRUMPETS, BEATEN — THE ARAMAIC WRITES THE TWO. "{H(10, 2, "עשה", "לך", "שתי", "חצוצרת", "כסף")}" ("make for yourself two trumpets of silver" — the construct "two of", the parser\'s gap: 10:2 → [], computed) → {A(10, 2, "עביד", "לך", "תרתין", "חצוצרן", "דכסף")} ("make for yourself TWO trumpets of silver") — the translation writes the numeral the parser cannot read; "{H(10, 2, "מקשה", "תעשה", "אתם")}" ("beaten shall you make them") → {A(10, 2, "נגיד", "תעבד", "יתהון")} ("DRAWN shall you make them" — the lampstand\'s word at 8:4); "{H(10, 2, "למקרא", "העדה", "ולמסע", "את", "המחנות")}" ("for calling the congregation and for journeying the camps" — the two offices, one seat) → {A(10, 2, "לערעא", "כנשתא", "ולאטלא", "ית", "משריתא")} ("to summon the assembly and to move the camps"). The trumpet-word spelled THREE WAYS in the chapter — 10:2, 10:8-9, 10:10 (computed).')
row(10, 3, 'MATERIAL', f'BOTH — THE CONGREGATION. "{H(10, 3, "ותקעו", "בהן")}" ("and they shall blow with them") → {A(10, 3, "ויתקעון", "בהן")}; "{H(10, 3, "ונועדו", "אליך", "כל", "העדה")}" ("and all the congregation shall gather to you") → {A(10, 3, "ויזדמנון", "לותך", "כל", "כנשתא")} ("shall present themselves to you"); "to the door of the tent of meeting" — the Sifrei\'s place for the princes too (73:1).')
row(10, 4, 'MATERIAL', f'ONE — THE PRINCES. "{H(10, 4, "ואם", "באחת", "יתקעו")}" ("and if with one they blow" — the parser reads the one) → {A(10, 4, "ואם", "בחדא", "יתקעון")}; "{H(10, 4, "הנשיאים", "ראשי", "אלפי", "ישראל")}" ("the princes, the heads of the thousands of Israel") → {A(10, 4, "רברביא", "רישי", "אלפיא", "דישראל")} ("the great ones, the heads of the thousands of Israel") — "thousands" the noun, no number (the parser\'s dual rule: before a noun the plural — computed).')
row(10, 5, 'MATERIAL', f'THE TERUAH IS A WAIL. "{H(10, 5, "ותקעתם", "תרועה")}" ("and you shall blow a teruah" — the broken sound) → {A(10, 5, "ותתקעון", "יבבתא")} ("and you shall blow a WAILING") — the teruah rendered by the sobbing-word (the exam\'s Rosh Hashanah 33b derives the teruah\'s sound from THE TARGUM\'S "wailed" at Judg 5:28 — the translation layer load-bearing again, as at Bekhorot 50a); "{H(10, 5, "ונסעו", "המחנות", "החנים", "קדמה")}" ("and the camps that camp eastward shall journey") → {A(10, 5, "ויטלון", "משריתא", "דשרן", "קדומא")} ("and the camps that camp eastward shall move").')
row(10, 6, 'MATERIAL', f'A SECOND TERUAH; A TERUAH FOR THEIR JOURNEYS. "{H(10, 6, "ותקעתם", "תרועה", "שנית")}" ("and you shall blow a SECOND teruah" — the Sifrei\'s superfluous "second") → {A(10, 6, "ותתקעון", "יבבתא", "תנינות")}; "{H(10, 6, "ונסעו", "המחנות", "החנים", "תימנה")}" ("the camps that camp southward shall journey") → {A(10, 6, "ויטלון", "משריתא", "דשרן", "דרומא")}; "{H(10, 6, "תרועה", "יתקעו", "למסעיהם")}" ("a teruah shall they blow for their journeys" — "for their journeys" at four seats, computed) → {A(10, 6, "יבבא", "יתקעון", "למטלניהון")} ("a wailing they shall blow for their journeys"). The teruah-word three times in 10:5-6 (computed).')
row(10, 7, 'MATERIAL', f'THE ASSEMBLY — A TEKIAH, NOT A TERUAH. "{H(10, 7, "ובהקהיל", "את", "הקהל")}" ("and when the assembly is gathered") → {A(10, 7, "ובמכנש", "ית", "קהלא")}; "{H(10, 7, "תתקעו", "ולא", "תריעו")}" ("you shall blow and not sound a teruah") → {A(10, 7, "תתקעון", "ולא", "תיבבון")} ("blow and not WAIL") — the two sounds distinct in the ink\'s own negation (the Sifrei 73:2).')
